    "b": "$$M(r) = \\frac{1}{\\sqrt{(1-r^2)^2 + (2\\zeta r)^2}},\\qquad r = \\frac{\\omega}{\\omega_0}$$<b>讀法</b>：有阻尼時暫態會消失，剩下和外力同頻率的穩態振盪，振幅是靜態位移乘上 $M(r)$。$\\zeta \\lt  1/\\sqrt{2}$ 時有共振峰，位置在 $r = \\sqrt{1-2\\zeta^2}$，峰值 $1/(2\\zeta\\sqrt{1-\\zeta^2})$；阻尼很小時峰值約等於 $Q = 1/(2\\zeta)$。無阻尼且 $\\omega = \\omega_0$ 時，振幅隨時間線性無限長大。<br><br><b>小例子</b>（教材例題 2.7，MEMS 諧振器，教學用模型）：$m = 10^{-9}\\ \\text{kg}$、$k = 4\\ \\text{N/m}$、$\\zeta = 0.02$。<ul><li>$\\omega_0 \\approx 63246\\ \\text{rad/s}$，$f_0 \\approx 10.066\\ \\text{kHz}$，$Q = 25$，$M_{\\max} \\approx 25.005$。</li><li>驅動力 $4\\times 10^{-8}\\ \\text{N}$ 在 $r = 1$：靜態位移 $10\\ \\text{nm}$，穩態振幅 $25 \\times 10 = 250\\ \\text{nm}$，相位落後 $90^\\circ$。</li></ul>反過來想隔振：讓 $r \\gt  \\sqrt{2}$ 就有 $M \\lt  1$。例如 $r = 3$、$\\zeta = 0.1$ 時 $M \\approx 0.125$。"
