    "b": "<ul><li><b>第二平移定理用錯函數</b>：$\\mathcal{L}\\{g(t)u(t-a)\\}$ 要用 $e^{-as}\\mathcal{L}\\{g(t+a)\\}$，不是 $e^{-as}G(s)$。例如 $t\\,u(t-1)$ 要先寫成 $[(t-1)+1]u(t-1)$，答案是 $e^{-s}(\\frac{1}{s^2}+\\frac{1}{s})$。</li><li><b>不檢查條件就用終值定理</b>：只有 $sY(s)$ 的極點全在左半平面時才成立。$Y=\\frac{1}{s(s-1)}$ 硬套會得到 $-1$，但真正的 $y=e^t-1$ 會發散。</li><li><b>把 $\\mathcal{L}\\{fg\\}$ 當成 $F(s)G(s)$</b>：$s$ 域相乘對應的是時域摺積，不是時域相乘。$\\mathcal{L}\\{t\\sin3t\\}$ 要用 $s$ 域微分 $-\\frac{d}{ds}\\frac{3}{s^2+9}=\\frac{6s}{(s^2+9)^2}$。</li></ul>"
