  "notes": [
   {
    "h": "一句話記住",
    "b": "線性系統的問題全都寫成 Ax＝b：用高斯消去法解，用秩判斷有沒有解，用條件數判斷解能不能信，解不到就用最小平方法找最接近的答案。"
   },
   {
    "h": "為什麼需要它",
    "b": "三迴路的電阻網路，KVL 給出三條方程式，手算代入還應付得來。可是電路模擬軟體面對的是成千上萬個節點。<br>直覺做法是克萊姆法則，但如果行列式用餘因子展開，$n$ 階要做大約 $n!$ 次運算：$n=25$ 時 $25!\\approx 1.55\\times 10^{25}$，而高斯消去法只要約 $\\tfrac{2}{3}n^3\\approx 10417$ 次。<br>就算方法對了，還有第二道牆：浮點誤差。以 8 階希爾伯特矩陣為例（條件數約 $1.5\\times10^{10}$），在右側加上相對大小約 $6.9\\times10^{-11}$ 的雜訊，解的相對誤差就跳到約 $2.8\\times10^{-2}$，放大了四億倍左右。<br>本集的工具剛好對應這兩道牆：高斯消去法讓大系統算得動，條件數告訴你算出來的數字有幾位可信。"
   },
   {
    "h": "高斯消去法與解的判定",
    "b": "三種基本列運算（交換兩列、某列乘非零常數、某列的倍數加到另一列）不會改變解。用它們把增廣矩陣化成列梯形，再回代。\n<ol><li>寫出增廣矩陣 $[A\\mid\\mathbf{b}]$。</li><li>逐行消去主元下方的元素（電腦會先做部分選主元）。</li><li>數主元個數得到秩，套用下面的判定。</li><li>有解就由最後一列往上回代。</li></ol>\n$$\\operatorname{rank}(A)\\lt \\operatorname{rank}([A\\mid\\mathbf{b}])\\Rightarrow\\text{無解},\\qquad \\operatorname{rank}(A)=\\operatorname{rank}([A\\mid\\mathbf{b}])=n\\Rightarrow\\text{唯一解}$$\n兩個秩相等但小於 $n$ 時有無窮多解，自由參數有 $n-r$ 個。<br>例子：網目方程 $4i_1-i_2-i_3=12$、$-i_1+4i_2-i_3=0$、$-i_1-i_2+4i_3=6$ 消去後最後一列是 $\\tfrac{10}{3}i_3=10$，回代得 $i_3=3$、$i_2=1.8$、$i_1=4.2$（單位 A）。另一個例子：係數矩陣 $\\begin{bmatrix}1&2&1\\\\2&4&3\\\\3&6&k\\end{bmatrix}$、右側 $[1,3,4]^T$，消去後最後一列變成 $[0\\ 0\\ 0\\mid 4-k]$，所以 $k\\ne4$ 無解，$k=4$ 有無窮多解 $\\mathbf{x}=[0,0,1]^T+t[-2,1,0]^T$。"
   },
   {
    "h": "行列式、反矩陣與它們的代價",
    "b": "行列式是體積的縮放倍率，等於 0 就代表空間被壓扁，資訊遺失、無法還原。\n$$A \\text{ 可逆}\\iff \\det A\\ne 0\\iff \\operatorname{rank}(A)=n,\\qquad \\det(AB)=\\det A\\,\\det B$$\n實用性質：上三角矩陣的行列式就是對角線相乘；某列倍數加到另一列不改變行列式。所以網目矩陣消去後的對角線 $4,\\tfrac{15}{4},\\tfrac{10}{3}$ 相乘就得 $\\det A=50$。<br>反矩陣用高斯－喬登法：把 $[A\\mid I]$ 化成 $[I\\mid A^{-1}]$。例如 $A=\\begin{bmatrix}1&2&0\\\\0&1&1\\\\2&3&1\\end{bmatrix}$（$\\det A=2$）得到 $A^{-1}=\\begin{bmatrix}-1&-1&1\\\\1&0.5&-0.5\\\\-1&0.5&0.5\\end{bmatrix}$。<br>寫程式時別先算 inv(A) 再乘 b，直接呼叫 np.linalg.solve(A, b) 比較快也比較準。"
   },
   {
    "h": "條件數與最小平方法",
    "b": "<b>條件數</b>：右側有誤差 $\\delta\\mathbf{b}$ 時，解的相對誤差最多被放大 $\\kappa(A)$ 倍。雙精度大約 16 位有效數字，若 $\\kappa\\approx10^k$，最多可能損失約 $k$ 位。網目矩陣的特徵值是 $2,5,5$，$\\kappa_2=5/2=2.5$，非常良態；12 階希爾伯特矩陣的 $\\kappa_2\\approx1.6\\times10^{16}$，雙精度下的解幾乎不可信。<br><b>最小平方</b>：量測點比參數多時（$m\\gt n$），$\\mathbf{b}$ 通常不在行空間裡，改求 $\\|\\mathbf{b}-A\\mathbf{x}\\|_2$ 最小。最短的殘差要垂直於行空間，於是\n$$A^T(\\mathbf{b}-A\\hat{\\mathbf{x}})=\\mathbf{0}\\ \\Longrightarrow\\ A^TA\\hat{\\mathbf{x}}=A^T\\mathbf{b}$$\n例子：感測器資料 $t=0,1,2,3$、$y=1.0,2.9,5.1,7.0$，得 $A^TA=\\begin{bmatrix}4&6\\\\6&14\\end{bmatrix}$、$A^T\\mathbf{y}=[16.0,34.1]^T$，解出 $y=0.97+2.02t$，殘差長度約 $0.134$。<br>注意：直接組 $A^TA$ 會讓條件數平方，$A$ 偏病態時改用 QR 或 SVD（np.linalg.lstsq 用的就是 SVD）。"
   },
   {
    "h": "電子／電機連結",
    "b": "<ul><li><b>電路模擬</b>：SPICE 類電路模擬器用修正節點分析（Modified Nodal Analysis）把整張電路寫成一個大型線性系統，每個工作點、每個時間步都要解一次，內部用的是 LU 分解，也就是高斯消去法的矩陣版本。</li><li><b>神經網路</b>：全連接層的前向傳播是 $Y=XW+\\mathbf{1}_N\\mathbf{b}$，一整批輸入一次做矩陣乘法。GPU 的 Tensor Core 就是專門加速這種矩陣乘法的硬體。</li><li><b>感測與校正</b>：感測器、ADC 的增益與偏移校正，常用多筆量測點做最小平方擬合；多項式階數拉太高時，萬德蒙矩陣的條件數會暴增，這時就該換用 QR 或 SVD 求解。</li></ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul><li><b>以為方程式數等於未知數就有唯一解</b>：方程式可能彼此重複或矛盾，要比較 $\\operatorname{rank}(A)$、$\\operatorname{rank}([A\\mid\\mathbf{b}])$ 和 $n$。</li><li><b>把矩陣乘法當成可交換</b>：一般 $AB\\ne BA$，而且 $AB=0$ 不代表 $A$ 或 $B$ 是零矩陣；轉置要反序，$(AB)^T=B^TA^T$。</li><li><b>看到殘差很小就相信解</b>：病態系統裡殘差可以很小、解卻錯很多。要看條件數；最小平方問題也別習慣性地組 $A^TA$，它會把條件數平方。</li></ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul><li>7.1 節：矩陣的大小、轉置、對稱與斜對稱的定義。</li><li>7.2 節：矩陣乘法的行組合觀點、三個反直覺性質，以及線性層 $Y=XW+\\mathbf{b}$。</li><li>7.3 節：增廣矩陣、三種基本列運算、回代，與部分選主元的理由。</li><li>7.4 節：線性獨立的定義，秩等於主元個數。</li><li>7.5 節：用兩個秩判斷無解、唯一解、無窮多解，以及秩－零度定理。</li><li>7.6 節：行列式的體積意義、列運算對行列式的影響，克萊姆法則為何不適合大系統。</li><li>7.7 節：高斯－喬登法求反矩陣，以及「解系統不要先求反矩陣」。</li><li>7.8 節：四大基本子空間的維度與正交關係。</li><li>7.9 節：條件數的誤差界、正規方程的投影推導與條件數平方問題。</li></ul>"
   }
  ],
