   "intro": "假設一塊功率晶片的散熱基板，溫度分布用教學模型 $T(x,y,z)=100\\,e^{-(x^2+2y^2+z^2)}$（°C，座標單位 cm）描述，熱源在原點。我們在點 $P(1,0,1)$ 放了一顆溫度感測器。",
