    "h": "電子／電機連結",
    "b": "<ul><li><b>電力電子</b>：PWM 的直流成分 $DV_0$ 是降壓轉換器的輸出電壓；全波整流 $|\\sin t|$ 的最低非零諧波是 2 倍頻，60 Hz 市電整流後的漣波就在 120 Hz。總諧波失真 THD 用 Parseval 的諧波功率來定義。</li><li><b>通訊</b>：Wi-Fi、LTE、5G NR 採用 OFDM，發射端用 IFFT 把資料放到許多子載波上，接收端用 FFT 拆回來；調變定理就是載波搬移頻譜的數學。</li><li><b>資料擷取與音訊</b>：CD 音訊用 44.1 kHz 取樣，高於人耳上限約 20 kHz 的兩倍；示波器與頻譜分析儀的 FFT 模式都提供 Hann、Flat-top 等窗函數選項。</li></ul>"
