    "b": "<ul><li><b>分離常數取錯符號</b>：兩端固定的問題若取 $k\\gt 0$，只會得到零解。正確是先討論 $k$ 的正負，用邊界條件篩出 $k=-p^2$。絕熱邊界（Neumann）則篩出餘弦模態，還多一個 $n=0$ 的常數項。</li><li><b>非齊次邊界直接套級數</b>：兩端溫度不是 0 時，正弦級數在端點永遠是 0，對不上邊界值。要先減掉穩態解 $u_s$，對 $w=u-u_s$ 用級數，初始條件也要改成 $f-u_s$。</li><li><b>把熱方程和波動方程的時間因子搞混</b>：波動方程時間是二階，模態乘 $\\cos\\lambda_nt$、$\\sin\\lambda_nt$，會一直振盪；熱方程是一階，乘 $e^{-\\lambda_n^2t}$，只會衰減。另外，PINN 的損失函數很小，不等於解的誤差很小，仍要和解析解或可信的數值解比對。</li></ul>"
