    "b": "<ul><li><b>因果性與 Kramers–Kronig</b>：因果的線性非時變系統，脈衝響應在 $t\\lt 0$ 為零，頻率響應延伸到上半複平面是解析的，用半圓圍道就推出實部與虛部互為希爾伯特轉換。對介電材料，這代表吸收（虛部）和色散（實部、折射率）綁在一起，不能只改一邊。以單極點響應 $\\chi(\\omega)=\\frac{1}{1-i\\omega\\tau}$ 驗算：$\\chi_2=\\frac{\\omega\\tau}{1+\\omega^2\\tau^2}$，代入關係式在 $\\omega=0$ 得 $\\frac1\\pi\\int\\frac{\\tau}{1+\\omega'^2\\tau^2}d\\omega'=1=\\chi_1(0)$。</li><li><b>電路靈敏度與複步微分</b>：最佳化或敏感度分析要大量算導數。以教材的測試函數 $g(x)=\\frac{e^x}{\\cos^3x+\\sin^3x}$ 在 $x=1.5$ 實算：中心差分最好只到相對誤差約 $3\\times10^{-10}$（$h=10^{-5}$），$h=10^{-13}$ 時惡化到約 $2\\times10^{-3}$；複步微分在 $h\\le10^{-10}$ 時誤差約 $10^{-16}$。限制是程式裡不能有 abs、max 這類非解析運算。</li><li><b>二維靜電場的平均值性質</b>：把 Cauchy 公式用在圓周上，得到圓心的值＝圓周上的平均。無電荷區域的電位是調和函數，所以內部不會有比周圍都高的電位極大值。</li></ul>"
