    "b": "<ul><li><b>數位濾波器的 Z 轉換</b>：因果訊號的 $H(z)=\\sum h[n]z^{-n}$ 是 $w=z^{-1}$ 的冪級數，收斂區域是最大極點以外 $|z|\\gt \\max|p_k|$。BIBO 穩定等於單位圓落在收斂區域裡，也就是所有極點都在單位圓內。例題 15.4 的 $\\frac{1}{(1-0.5z^{-1})(1-0.8z^{-1})}$，部分分式得 $A=-\\frac53$、$B=\\frac83$，$h[n]=\\frac83(0.8)^n-\\frac53(0.5)^n$；用 lfilter 實算前六點 $1,\\ 1.3,\\ 1.29,\\ 1.157,\\ 0.9881,\\ 0.8217$，與公式一致。極點若是 1.1，$1.1^n$ 永不衰減。</li><li><b>小訊號模型</b>：二極體、MOSFET 的小訊號分析，就是把非線性的電流電壓關係在偏壓點做 Taylor 展開、只留一次項；輸入振幅太大時高次項不可忽略，就會出現諧波失真。</li><li><b>數學函式庫與韌體</b>：處理器算 $e^x$、$\\sin x$ 時，常把輸入範圍縮小後用截斷的多項式或有理函數近似，再用誤差上界確保整個範圍都達到要求精度。M-test 給的正是「整個區間一致」的上界。</li></ul>"
