    "b": "<ul><li><b>缺項級數直接套比值公式</b>：$\\sum\\frac{z^{2k}}{4^k}$ 若把係數當成 $\\frac1{4^k}$ 算出 $R=4$ 就錯了，因為那是 $z^2$ 的半徑。正確做法是對整個一般項用比值或根值法，得 $|z|\\lt 2$。</li><li><b>只看實數線判斷收斂範圍</b>：$\\frac{1}{1+x^2}$ 在實軸上沒有奇點，但收斂半徑仍是 1。要把函數放到複平面上找所有奇點，取最近的距離。</li><li><b>把 Z 轉換的收斂區域方向弄反</b>：因果系統的級數是 $z^{-1}$ 的冪級數，收斂區域是圓的「外面」$|z|\\gt r_{\\max}$，不是裡面。判斷穩定性看單位圓是否在收斂區域內，等價於極點的模是否都小於 1。</li></ul>"
