    "b": "$$w=T(z)=\\frac{az+b}{cz+d},\\qquad ad-bc\\neq 0$$\n讀法：它可以拆成四步：\n<ol><li>平移 $z+d/c$</li><li>反演 $1/z$</li><li>旋轉縮放，乘上 $\\frac{bc-ad}{c^2}$</li><li>再平移 $a/c$</li></ol>\n平移、旋轉、縮放本來就把圓送到圓，反演也把廣義圓送到廣義圓，所以 Möbius 轉換有<b>保圓性</b>：經過極點的圓會變直線，不經過的仍是圓。兩個轉換的合成，等於係數矩陣 $\\begin{bmatrix}a&b\\\\c&d\\end{bmatrix}$ 相乘。<br><b>小例子</b>：直線 $x=c$ 經 $w=1/z$ 變成圓心 $\\left(\\frac{1}{2c},0\\right)$、半徑 $\\frac{1}{2c}$ 的圓，通過 $w=0$（直線的無窮遠點）。<br>要把三點 $z_1,z_2,z_3$ 送到 $w_1,w_2,w_3$，令兩邊交比相等就得到唯一的轉換。把虛軸上的 $(0,i,\\infty)$ 送到 $(-1,i,1)$，解出 $w=\\frac{z-1}{z+1}$，右半平面整個進了單位圓盤，$z=1$ 落在圓心。"
