    "b": "$$\\Gamma=\\frac{z-1}{z+1},\\qquad z=\\frac{1+\\Gamma}{1-\\Gamma}$$\n讀法：被動負載 $r\\ge 0$ 全部落在 $|\\Gamma|\\le 1$；匹配點 $z=1$ 在圓心，開路在 $\\Gamma=1$，短路在 $\\Gamma=-1$。阻抗平面的直角格線變成兩族圓：\n<ul><li>等電阻圓：圓心 $\\left(\\frac{r}{r+1},0\\right)$、半徑 $\\frac{1}{r+1}$，全部相切於 $\\Gamma=1$。</li><li>等電抗圓弧：圓心 $\\left(1,\\frac1x\\right)$、半徑 $\\frac{1}{|x|}$；上半是電感性，下半是電容性。</li></ul>\n因為映射保角，兩族圓處處垂直。<b>小例子</b>：$Z_L=(25+j50)\\,\\Omega$，$\\Gamma\\approx 0.0769+j0.6154$，$|\\Gamma|\\approx 0.620$，VSWR $\\approx 4.27$。<br>其他常用映射：$w=e^z$ 把帶狀區 $0\\lt y\\lt \\pi$ 送到上半平面，再接 $w=\\frac{\\zeta-i}{\\zeta+i}$ 就到單位圓盤；Joukowsky 轉換 $w=z+\\frac{c^2}{z}$ 把 $|z|=c$ 壓成線段 $[-2c,2c]$，把通過臨界點 $z=c$ 的偏心圓變成翼型。它建立在二維、無黏、無旋的理想流假設上，預測不了失速與黏性阻力，現代設計以三維 CFD 為主。<br>黎曼映射定理保證任何單連通且不是整個平面的區域都能映到單位圓盤，但只保證存在，實際公式還得靠 Schwarz–Christoffel 轉換或數值方法。"
