    "b": "關鍵事實：若 $w=f(z)$ 解析，$\\Phi^*(u,v)$ 在 $w$ 平面調和，則拉回來的 $\\Phi(x,y)=\\Phi^*(u(x,y),v(x,y))$ 也調和，因為\n$$\\Phi_{xx}+\\Phi_{yy}=\\left(\\Phi^*_{uu}+\\Phi^*_{vv}\\right)|f'(z)|^2$$\n解題四步：\n<ol><li>畫出原區域與邊界條件（固定位勢，或絕熱、無通量）。</li><li>挑一個保角映射，把區域變成帶狀、上半平面或同心圓環，邊界條件跟著搬。</li><li>在新區域寫出簡單的調和解。</li><li>把 $u(x,y)$、$v(x,y)$ 代回去。</li></ol>\n<b>小例子 1</b>：第一象限，正實軸 $\\Phi=0$、正虛軸 $\\Phi=V_0$。$w=z^2$ 攤成上半平面，解是 $\\frac{V_0}{\\pi}\\arg w$，代回得 $\\Phi=\\frac{2V_0}{\\pi}\\arctan\\frac{y}{x}$。<br><b>小例子 2</b>：偏心同軸線，外圓 $|z|=1$、內圓 $|z-0.4|=0.25$。$w=\\frac{z-a}{1-az}$ 取 $a\\approx 0.4327$，內圓變成半徑 $\\rho\\approx 0.3023$ 的同心圓，電容 $\\frac{2\\pi\\varepsilon}{\\ln(1/\\rho)}$。<br>同一套數學搬到熱傳：$F=T+i\\Psi$，等溫線 $T=c$、熱流線 $\\Psi=c$，絕熱邊界本身就是一條熱流線。上半平面底邊 $|x|\\lt 1$ 維持 $T_1$、其餘 $T_0$ 時，$T=T_0+\\frac{T_1-T_0}{\\pi}\\left[\\arg(z-1)-\\arg(z+1)\\right]$，等溫線是通過 $(\\pm1,0)$ 的圓弧。搬到理想流：$F'(z)=V_1-iV_2$，$F'=0$ 是停滯點。"
