   {
    "h": "經典分布與中央極限定理",
    "b": "<table>\n<tr><th>分布</th><th>用在哪</th><th>平均數</th><th>變異數</th></tr>\n<tr><td>二項 $\\text{Bin}(n,p)$</td><td>$n$ 個位元中錯幾個</td><td>$np$</td><td>$np(1-p)$</td></tr>\n<tr><td>卜瓦松 $\\text{Poisson}(\\lambda)$</td><td>單位時間封包數、稀有缺陷數</td><td>$\\lambda$</td><td>$\\lambda$</td></tr>\n<tr><td>常態 $\\mathcal{N}(\\mu,\\sigma^2)$</td><td>熱雜訊、量測誤差</td><td>$\\mu$</td><td>$\\sigma^2$</td></tr>\n<tr><td>指數 $\\text{Exp}(\\lambda)$</td><td>等待時間、無老化元件壽命</td><td>$1/\\lambda$</td><td>$1/\\lambda^2$</td></tr>\n</table>\n小例子：位元錯誤率 $10^{-4}$、封包 $10^4$ 位元，二項分布精確算 $P(X\\le 1)\\approx 0.73576$，卜瓦松近似 $2e^{-1}\\approx 0.73576$，差距在小數第 9 位。請求以每秒 4 次的卜瓦松過程到達：1 秒內恰好 2 次的機率 $8e^{-4}\\approx 0.1465$，相鄰間隔超過 0.5 秒的機率 $e^{-2}\\approx 0.1353$。<br><br>\n多次量測取平均時，i.i.d. 且變異數有限就有\n$$E[\\bar{X}_n]=\\mu,\\qquad \\text{Var}(\\bar{X}_n)=\\frac{\\sigma^2}{n},\\qquad \\frac{\\bar{X}_n-\\mu}{\\sigma/\\sqrt{n}}\\xrightarrow{d}\\mathcal{N}(0,1)$$\n讀法：平均 $n$ 次，誤差的標準差縮成 $1/\\sqrt{n}$，而且分布形狀趨近鐘形，不管原本長怎樣。蒙地卡羅積分就是用這個：抽 $N$ 個樣本取平均，標準誤 $\\sigma_g/\\sqrt{N}$，與維度無關。代價是要把誤差縮 10 倍得多抽 100 倍樣本。柯西分布這類變異數不存在的重尾分布，平均數根本不收斂，CLT 不適用。"
   },
   {
    "h": "熵、交叉熵與 KL 散度",
    "b": "$$H(P)=-\\sum_x P(x)\\ln P(x),\\quad H(P,Q)=-\\sum_x P(x)\\ln Q(x),\\quad D_{\\text{KL}}(P\\,\\|\\,Q)=H(P,Q)-H(P)\\ge 0$$\n讀法：熵是平均的「驚訝程度」；用錯的模型 $Q$ 去預測真實的 $P$，平均驚訝度變成交叉熵，多出來的部分就是 KL 散度。吉布斯不等式保證它不會是負的，等號只在 $P=Q$ 時成立。<br><br>\n教材例（單位 nat）：真實軟標籤 $P=(0.7,0.2,0.1)$。\n<ul>\n<li>$H(P)\\approx 0.8018$。</li>\n<li>模型 $Q_1=(0.6,0.3,0.1)$：$H(P,Q_1)\\approx 0.8286$，$D_{\\text{KL}}(P\\,\\|\\,Q_1)\\approx 0.0268$。</li>\n<li>模型 $Q_2=(0.1,0.2,0.7)$：$D_{\\text{KL}}(P\\,\\|\\,Q_2)=0.6\\ln 7\\approx 1.1675$，猜錯方向被重罰。</li>\n<li>反過來算 $D_{\\text{KL}}(Q_1\\,\\|\\,P)\\approx 0.0291$，和 $0.0268$ 不同，所以 KL 散度不是距離。</li>\n</ul>\n因為 $H(P)$ 跟模型參數無關，最小化分類器的交叉熵損失就等於最小化 $D_{\\text{KL}}(P\\,\\|\\,Q_\\theta)$。"
   },
   {
    "h": "電子／電機連結",
    "b": "<ul>\n<li><b>數位通訊的位元錯誤率</b>：加成性白高斯雜訊（AWGN）通道下，BPSK 的位元錯誤率是 $Q\\big(\\sqrt{2E_b/N_0}\\big)$，$Q$ 就是標準常態的右尾機率。例如 $E_b/N_0=9.6$ dB 時約 $9.7\\times 10^{-6}$。封包內錯誤位元數則用二項或卜瓦松分布描述。</li>\n<li><b>半導體良率與可靠度</b>：晶圓上的隨機缺陷數常用卜瓦松模型，晶片零缺陷的機率是 $e^{-\\lambda}$，這是經典的卜瓦松良率模型；元件在使用中期（浴缸曲線平坦段）的壽命常用指數分布，串聯系統失效率相加。</li>\n<li><b>AI 分類器</b>：Softmax 輸出接交叉熵損失是深度學習分類的標準做法；變分自編碼器（VAE）的損失裡也有一項 KL 散度。通道容量的概念則直接來自 Shannon 1948 年的論文。</li>\n</ul>"
   },
   {
    "h": "常見陷阱",
    "b": "<ul>\n<li><b>把互斥當成獨立</b>：兩個機率都大於 0 的互斥事件，$P(A\\cap B)=0\\ne P(A)P(B)$，它們其實強烈相依（一個發生，另一個就不可能）。</li>\n<li><b>把 $P(A\\mid B)$ 當成 $P(B\\mid A)$</b>：靈敏度 98% 是 $P(\\text{報警}\\mid\\text{瑕疵})$，你要的是 $P(\\text{瑕疵}\\mid\\text{報警})$。忽略先驗基準率就會犯基準率謬誤，必須用貝氏定理換算。</li>\n<li><b>以為相關係數 0 就是獨立</b>：$X$ 等機率取 $-1,0,1$、$Y=X^2$ 時 $\\text{Cov}(X,Y)=0$，但 $P(X=0,Y=1)=0\\ne \\tfrac13\\cdot\\tfrac23$。只有聯合常態時，不相關才等於獨立。</li>\n</ul>"
   },
   {
    "h": "對照教材",
    "b": "<ul>\n<li><b>24.1 節</b>：平均數、中位數、$s^2$（分母 $n-1$）、IQR 與 $1.5\\,\\text{IQR}$ 離群值規則，看例題 24.1 一個壞點的影響。</li>\n<li><b>24.2 節</b>：樣本空間、事件與集合運算，記住笛摩根定律。</li>\n<li><b>24.3 節</b>：三條機率公理、條件機率、獨立的定義、全機率定理；分清互斥與獨立。</li>\n<li><b>24.4 節</b>：貝氏定理各項的名稱（先驗、概似度、事後），例題 24.2 的基準率謬誤；排列組合是後面二項分布的計數基礎。</li>\n<li><b>24.5 節</b>：CDF、PMF、PDF 的關係；連續型單點機率為 0。</li>\n<li><b>24.6 節</b>：期望值線性性、$\\text{Var}=E[X^2]-(E[X])^2$、柴比雪夫不等式、MGF 求動差。</li>\n<li><b>24.7 節</b>：二項、卜瓦松、超幾何、常態、指數五個分布的用途與平均數、變異數；指數分布的無記憶性。</li>\n<li><b>24.8 節</b>：聯合與邊際分布、共變異數、相關係數；不相關不等於獨立的反例。</li>\n<li><b>24.9 節</b>：大數法則、中央極限定理的條件（有限變異數）、蒙地卡羅的 $O(N^{-1/2})$ 誤差。</li>\n<li><b>24.10 節</b>：熵、交叉熵、KL 散度的關係與吉布斯不等式；Forward 與 Reverse KL 的差別。</li>\n</ul>"
   }
